text:
Here's a water tracker with a goal of 8 glasses. Tap + after each glass, tap − if you tap by mistake, and it resets each day.

```page
<!DOCTYPE html>
<html>
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<style>
  body { font-family: Segoe UI, sans-serif; text-align: center; padding: 24px; background: #f2f8fc; color: #12324a; }
  h1 { font-size: 20px; margin: 0 0 4px; }
  .date { font-size: 13px; opacity: .7; margin-bottom: 16px; }
  .count { font-size: 48px; font-weight: 600; margin: 8px 0; }
  .glasses { display: flex; flex-wrap: wrap; justify-content: center; gap: 8px; margin: 16px auto; max-width: 320px; }
  .g { width: 56px; height: 56px; border-radius: 10px; border: 2px solid #4aa3df; background: #fff; font-size: 26px; line-height: 52px; }
  .g.full { background: #4aa3df; }
  .bar { height: 10px; max-width: 320px; margin: 12px auto; background: #d7e8f4; border-radius: 5px; overflow: hidden; }
  .fill { height: 100%; width: 0; background: #4aa3df; transition: width .2s; }
  button { font-size: 22px; width: 64px; height: 64px; border-radius: 50%; border: none; background: #4aa3df; color: #fff; margin: 8px; cursor: pointer; }
  button.minus { background: #9db8cc; }
  .reset { font-size: 13px; width: auto; height: auto; border-radius: 6px; padding: 6px 12px; background: transparent; color: #12324a; border: 1px solid #9db8cc; }
  .msg { min-height: 22px; font-weight: 600; color: #1d7a4d; }
</style>
</head>
<body>
  <h1>Water today</h1>
  <div class="date" id="date"></div>
  <div class="count"><span id="n">0</span> / 8</div>
  <div class="bar"><div class="fill" id="fill"></div></div>
  <div class="glasses" id="glasses"></div>
  <div class="msg" id="msg"></div>
  <button class="minus" id="minus">−</button>
  <button id="plus">+</button>
  <div><button class="reset" id="reset">Reset today</button></div>

<script>
  var GOAL = 8;
  var today = new Date().toISOString().slice(0, 10);
  var key = "water-" + today;
  var count = 0;
  var store = null;
  try { store = window.localStorage; count = parseInt(store.getItem(key) || "0", 10) || 0; } catch (e) { store = null; }

  document.getElementById("date").textContent = new Date().toDateString();

  function save() { try { if (store) store.setItem(key, String(count)); } catch (e) {} }

  function draw() {
    document.getElementById("n").textContent = count;
    document.getElementById("fill").style.width = Math.min(100, count / GOAL * 100) + "%";
    var box = document.getElementById("glasses");
    box.innerHTML = "";
    for (var i = 0; i < GOAL; i++) {
      var d = document.createElement("div");
      d.className = "g" + (i < count ? " full" : "");
      d.textContent = i < count ? "💧" : "";
      box.appendChild(d);
    }
    document.getElementById("msg").textContent =
      count >= GOAL ? "Goal reached. Well done!" : (GOAL - count) + " more to go";
  }

  document.getElementById("plus").onclick = function () { count++; save(); draw(); };
  document.getElementById("minus").onclick = function () { if (count > 0) count--; save(); draw(); };
  document.getElementById("reset").onclick = function () { count = 0; save(); draw(); };
  draw();
</script>
</body>
</html>
```

If your count doesn't stay after closing the page, your device isn't letting it save. Want a version with a 7-day history?
